const tr={en:{back:'← Back to the site',kicker:'Faith · history · tradition',title:'Our Lady<br>of the Madia',subtitle:'Monopoli’s patron saint and a story joining sea, city and Cathedral Basilica.',imageCredit:'see author and licence',storyKicker:'01 / The tradition',storyTitle:'The icon from the sea.',storyText:'According to local tradition, on 16 December 1117 an icon of the Virgin arrived in Monopoli’s harbour on a raft. Its beams were used to complete the roof of the cathedral then under construction. The story remains part of the city’s living devotion.',historyNote:'The Diocese notes literary elements in the account of the arrival and dates the venerated icon to the 13th century. Tradition and historical research should be understood in their respective contexts.',december:'The city remembers the icon’s arrival with an annual re-enactment.',august:'The patron saint is also celebrated solemnly in summer.',basilicaKicker:'02 / The sanctuary',basilicaTitle:'The Cathedral Basilica.',basilicaText:'Dedicated to Our Lady of the Madia, the Cathedral Basilica is one of Monopoli’s landmarks. Its original construction dates to the 12th century; it was rebuilt in the 18th century and has a monumental Baroque design.',visitNote:'For services, opening times and visits, check with the Diocese and Municipality as schedules can change.',sourcesTitle:'Sources and further reading',book:'The book “La Madonna di Monopoli” on Amazon ↗',footer:'An independent cultural project by Rodrigo Locoselli.'},fr:{back:'← Retour au site',kicker:'Foi · histoire · tradition',title:'Notre-Dame<br>de la Madia',subtitle:'La patronne de Monopoli et un récit qui unit la mer, la ville et sa basilique-cathédrale.',imageCredit:'voir auteur et licence',storyKicker:'01 / La tradition',storyTitle:'L’icône venue de la mer.',storyText:'Selon la tradition locale, le 16 décembre 1117 une icône de la Vierge arriva au port de Monopoli sur un radeau. Ses poutres servirent à achever le toit de la cathédrale alors en construction. Ce récit demeure vivant dans la dévotion de la ville.',historyNote:'Le diocèse relève des éléments littéraires dans le récit de l’arrivée et date l’icône vénérée du XIIIe siècle. Tradition et recherche historique doivent être comprises dans leurs contextes respectifs.',december:'La ville commémore l’arrivée de l’icône chaque année.',august:'La patronne est aussi célébrée solennellement en été.',basilicaKicker:'02 / Le sanctuaire',basilicaTitle:'La basilique-cathédrale.',basilicaText:'Dédiée à Notre-Dame de la Madia, la basilique-cathédrale est un symbole de Monopoli. La construction d’origine remonte au XIIe siècle ; l’édifice fut reconstruit au XVIIIe siècle dans un style baroque monumental.',visitNote:'Pour les offices, horaires et visites, consultez le diocèse et la ville.',sourcesTitle:'Sources et approfondissements',book:'Le livre « La Madonna di Monopoli » sur Amazon ↗',footer:'Un projet culturel indépendant de Rodrigo Locoselli.'},es:{back:'← Volver al sitio',kicker:'Fe · historia · tradición',title:'La Virgen<br>de la Madia',subtitle:'La patrona de Monopoli y un relato que une el mar, la ciudad y su basílica catedral.',imageCredit:'ver autor y licencia',storyKicker:'01 / La tradición',storyTitle:'El icono llegado del mar.',storyText:'Según la tradición local, el 16 de diciembre de 1117 un icono de la Virgen llegó al puerto de Monopoli en una balsa. Sus vigas se usaron para completar el techo de la catedral entonces en construcción. El relato sigue vivo en la devoción de la ciudad.',historyNote:'La diócesis señala elementos literarios en el relato de la llegada y data el icono venerado en el siglo XIII. Tradición e investigación histórica deben entenderse en sus respectivos contextos.',december:'La ciudad recuerda cada año la llegada del icono.',august:'La patrona se celebra solemnemente también en verano.',basilicaKicker:'02 / El santuario',basilicaTitle:'La basílica catedral.',basilicaText:'Dedicada a la Virgen de la Madia, la basílica catedral es un símbolo de Monopoli. La construcción original se remonta al siglo XII; fue reconstruida en el siglo XVIII con arquitectura barroca monumental.',visitNote:'Para celebraciones, horarios y visitas, consulta la diócesis y el ayuntamiento.',sourcesTitle:'Fuentes y más información',book:'El libro «La Madonna di Monopoli» en Amazon ↗',footer:'Un proyecto cultural independiente de Rodrigo Locoselli.'},pt:{back:'← Voltar ao site',kicker:'Fé · história · tradição',title:'Nossa Senhora<br>da Madia',subtitle:'A padroeira de Monopoli e uma história que une o mar, a cidade e a sua Basílica Catedral.',imageCredit:'ver autor e licença',storyKicker:'01 / A tradição',storyTitle:'O ícone vindo do mar.',storyText:'Segundo a tradição local, em 16 de dezembro de 1117 um ícone da Virgem chegou ao porto de Monopoli numa jangada. As suas vigas foram usadas para concluir o telhado da catedral então em construção. A história permanece viva na devoção da cidade.',historyNote:'A Diocese identifica elementos literários no relato da chegada e data o ícone venerado do século XIII. Tradição e pesquisa histórica devem ser entendidas nos seus respetivos contextos.',december:'A cidade recorda a chegada do ícone todos os anos.',august:'A padroeira também é celebrada solenemente no verão.',basilicaKicker:'02 / O santuário',basilicaTitle:'A Basílica Catedral.',basilicaText:'Dedicada a Nossa Senhora da Madia, a Basílica Catedral é um símbolo de Monopoli. A construção original remonta ao século XII; foi reconstruída no século XVIII com arquitetura barroca monumental.',visitNote:'Para celebrações, horários e visitas, consulte a Diocese e o Município.',sourcesTitle:'Fontes e aprofundamentos',book:'O livro “La Madonna di Monopoli” na Amazon ↗',footer:'Um projeto cultural independente de Rodrigo Locoselli.'}};const it={};document.querySelectorAll('[data-i]').forEach(x=>it[x.dataset.i]=x.innerHTML);function setLang(l){const d=tr[l]||it;document.documentElement.lang=l;document.querySelectorAll('[data-i]').forEach(x=>x.innerHTML=d[x.dataset.i]||it[x.dataset.i]);document.querySelectorAll('[data-lang]').forEach(x=>x.classList.toggle('active',x.dataset.lang===l));localStorage.setItem('monopoli-lang',l)}document.querySelectorAll('[data-lang]').forEach(x=>x.addEventListener('click',()=>setLang(x.dataset.lang)));setLang(localStorage.getItem('monopoli-lang')||'it');
